import sqlite3

def polacz(sciezka="stado.db"):
    con = sqlite3.connect(sciezka)
    con.execute("CREATE TABLE IF NOT EXISTS zwierzeta (id INTEGER PRIMARY KEY, imie TEXT, rasa TEXT, waga REAL)")
    return con

def dodaj(con, imie, rasa, waga):
    con.execute("INSERT INTO zwierzeta (imie, rasa, waga) VALUES (?, ?, ?)", (imie, rasa, waga))
    con.commit()

def pobierz(con):
    return con.execute("SELECT id, imie, rasa, waga FROM zwierzeta ORDER BY imie").fetchall()

from flask import Flask, render_template, request, redirect
import baza

app = Flask(__name__)

@app.route("/")
def lista():
    return render_template("lista.html", zwierzeta=baza.pobierz(baza.polacz()))

@app.route("/dodaj", methods=["GET", "POST"])
def dodaj():
    blad = None
    if request.method == "POST":
        imie = request.form.get("imie", "").strip()
        try:
            waga = float(request.form.get("waga", ""))
        except ValueError:
            waga = -1
        if not imie or waga <= 0:
            blad = "Podaj imię i wagę większą od zera."
        else:
            baza.dodaj(baza.polacz(), imie, request.form.get("rasa", ""), waga)
            return redirect("/")
    return render_template("dodaj.html", blad=blad)

if __name__ == "__main__":
    app.run(debug=True)
